from collections import deque
from datetime import date as _calendar_date
from decimal import Decimal, InvalidOperation
from fractions import Fraction


def fifo_report(trades: list[dict]) -> dict:
    def quantize_fraction(value, places):
        scale = 10 ** places
        scaled = value * scale
        if scaled >= 0:
            quotient, remainder = divmod(scaled.numerator, scaled.denominator)
            if 2 * remainder >= scaled.denominator:
                quotient += 1
            signed = quotient
        else:
            quotient, remainder = divmod(-scaled.numerator, scaled.denominator)
            if 2 * remainder >= scaled.denominator:
                quotient += 1
            signed = -quotient
        if signed == 0:
            return Decimal((0, (0,), -places))
        sign = 1 if signed < 0 else 0
        digits = tuple(int(ch) for ch in str(abs(signed)))
        return Decimal((sign, digits, -places))

    def parse_money(value, max_places, allow_zero):
        if not isinstance(value, str):
            raise ValueError('money value must be a string')
        try:
            amount = Decimal(value)
        except (InvalidOperation, ValueError, ArithmeticError):
            raise ValueError('invalid money value') from None
        if not amount.is_finite():
            raise ValueError('money value must be finite')
        if allow_zero:
            if amount < 0:
                raise ValueError('money value must not be negative')
        else:
            if amount <= 0:
                raise ValueError('money value must be positive')
        if amount.as_tuple().exponent < -max_places:
            raise ValueError('too many decimal places')
        return amount

    if not isinstance(trades, list):
        raise ValueError('trades must be a list')

    sales = []
    lots = deque()
    total_realized = Decimal('0.00')

    for trade in trades:
        if not isinstance(trade, dict):
            raise ValueError('trade must be a dict')
        if 'date' not in trade or 'side' not in trade or 'quantity' not in trade or 'price' not in trade:
            raise ValueError('trade missing required key')

        date_value = trade['date']
        if not isinstance(date_value, str):
            raise ValueError('date must be a string')
        if len(date_value) != 10 or date_value[4] != '-' or date_value[7] != '-':
            raise ValueError('date must be YYYY-MM-DD')
        date_digits = date_value[:4] + date_value[5:7] + date_value[8:10]
        if not all(ch in '0123456789' for ch in date_digits):
            raise ValueError('date must be YYYY-MM-DD')
        try:
            _calendar_date(int(date_value[:4]), int(date_value[5:7]), int(date_value[8:10]))
        except ValueError:
            raise ValueError('invalid calendar date') from None

        side_value = trade['side']
        if side_value != 'BUY' and side_value != 'SELL':
            raise ValueError('side must be BUY or SELL')

        quantity_value = trade['quantity']
        if isinstance(quantity_value, bool) or not isinstance(quantity_value, int):
            raise ValueError('quantity must be an int')
        if quantity_value <= 0:
            raise ValueError('quantity must be positive')

        price_value = parse_money(trade['price'], 4, False)
        if 'fee' in trade:
            fee_value = parse_money(trade['fee'], 2, True)
        else:
            fee_value = Decimal('0.00')

        if side_value == 'BUY':
            total_cost = Fraction(price_value) * quantity_value + Fraction(fee_value)
            lots.append([quantity_value, total_cost])
        else:
            inventory = 0
            for lot_quantity, lot_cost in lots:
                inventory += lot_quantity
            if inventory < quantity_value:
                raise ValueError('insufficient inventory')
            proceeds_exact = Fraction(price_value) * quantity_value - Fraction(fee_value)
            cost_consumed = Fraction(0, 1)
            to_take = quantity_value
            while to_take > 0:
                lot_quantity, lot_cost = lots[0]
                taken = lot_quantity if lot_quantity < to_take else to_take
                consumed = lot_cost * taken / lot_quantity
                cost_consumed += consumed
                to_take -= taken
                if taken == lot_quantity:
                    lots.popleft()
                else:
                    lots[0][0] = lot_quantity - taken
                    lots[0][1] = lot_cost - consumed
            proceeds_out = quantize_fraction(proceeds_exact, 2)
            cost_out = quantize_fraction(cost_consumed, 2)
            realized_out = quantize_fraction(proceeds_exact - cost_consumed, 2)
            sales.append({'date': date_value, 'quantity': quantity_value, 'proceeds': proceeds_out, 'cost': cost_out, 'realized': realized_out})
            total_realized += realized_out

    remaining = []
    inventory_quantity = 0
    for lot_quantity, lot_cost in lots:
        if lot_quantity > 0:
            inventory_quantity += lot_quantity
            remaining.append({'quantity': lot_quantity, 'unit_cost': quantize_fraction(lot_cost / lot_quantity, 4), 'total_cost': quantize_fraction(lot_cost, 2)})

    total_realized = quantize_fraction(Fraction(total_realized), 2)
    return {'sales': sales, 'total_realized': total_realized, 'remaining': remaining, 'inventory_quantity': inventory_quantity}
